<?php
require dirname(__DIR__).'/bootstrap.php';
use AranduGo\Auth;use AranduGo\Csrf;use AranduGo\Support;
Auth::requireLogin();Csrf::verify();if(empty($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)Support::json(['ok'=>false,'error'=>'Carga inválida'],422);if($_FILES['image']['size']>5*1024*1024)Support::json(['ok'=>false,'error'=>'Máximo 5 MB'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($types[$mime]))Support::json(['ok'=>false,'error'=>'Formato no permitido'],422);$name=date('Y/m');$dir=dirname(__DIR__).'/uploads/'.$name;if(!is_dir($dir)&&!mkdir($dir,0755,true))Support::json(['ok'=>false,'error'=>'No se pudo crear la carpeta'],500);$file=bin2hex(random_bytes(16)).'.'.$types[$mime];if(!move_uploaded_file($_FILES['image']['tmp_name'],$dir.'/'.$file))Support::json(['ok'=>false,'error'=>'No se pudo guardar'],500);Support::json(['ok'=>true,'url'=>Support::url('uploads/'.$name.'/'.$file)]);
